def delete_plugin_config(self, pid: str, force: bool=False) -> bool:
    """
        删除插件配置
        :param pid: 插件ID
        :param force: 插件停止后仍允许按插件 ID 删除持久化配置
        """
    if not force and (not self._plugins.get(pid)):
        return False
    return SystemConfigOper().delete(self._config_key % pid)
